 "content": "def transform(grid):
    """Recolor the largest zero-connected region 8 and smallest 7."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append(cells)
    out = [row[:] for row in grid]
    if not components:
        return out
    smallest = min(components, key=len)
    largest = max(components, key=len)
    for r, c in smallest:
        out[r][c] = 7
    for r, c in largest:
        out[r][c] = 8
    return out
